export default function PortfolioGrid({ proyectos = [], home = false }){
  const lista = home ? proyectos.filter(p => p.tipo === 2) : proyectos

  return (
    <>
      <div className="d-flex flex-md-row flex-column justify-content-between align-items-center my-5">
          <h2 className="fw-bold mb-md-0 text-white"><i className="fas fa-code"></i> Algunos de mis proyectos</h2>
          {home && proyectos.length > 6 ? (
            <a href="/proyectos" className="mas-proyectos titulo btn btn-outline-light">Ver más proyectos...</a>
          ) : null}
      </div>

      <div className="row my-5 pb-5" id="listado">
        {lista.map(p => (
          <div className="col-md-6 col-xl-4 mt-4 portafolio Anime" key={p.id}>
            <a href={p.link} className="text-white" rel="noopener noreferrer" target="_blank">
              <div className="proyecto rounded position-relative aa">
                <h2 className="fs-5 titel position-absolute top-0 start-50 translate-middle-x w-100 text-center py-1">{p.tecnologias}</h2>
                <img src={`/img/${p.id}.png`} className="img-fluid mx-auto w-100 h-100" alt={`imagen ${p.nombre}`}/>
                <div className="position-absolute top-50 start-50 translate-middle w-75 bb">
                  <h2 className="text-center fs-1 fw-bold text-uppercase">{p.nombre}</h2>
                  <p className="text-center">{p.desc}</p>
                  <p className="fs-6 text-center">Subido: {p.fecha}</p>
                </div>
              </div>
            </a>
          </div>
        ))}
      </div>
    </>
  )
}
