import datos from '../datos.json'
import Head from 'next/head'
import PortfolioGrid from '../components/PortfolioGrid'

export default function Home({ proyectos }) {
  return (
    <>
      <Head>
        <title>Portafolio</title>
      </Head>

      <div className="hero mb-5">
        <div className="container-fluid m-0">
            <div className="row">
                <div className="col-6 d-none d-md-flex bg-claro">
                    <img src="/img/logo1.png" className="img-fluid align-self-center p-5" alt="" />
                </div>
                <div className="col-12 col-md-6 bg-oscuro d-flex text-center text-md-start">
                    <div className="align-self-center justify-content-center p-5">
                        <h1 hidden>Programador - Frontend - react - desarrollador web</h1>
                        <h2 className="fs-1">Desarrollador Front End</h2>           
                        <p className="fs-4 my-3">
                            ¿Quieres crear páginas web con increíbles diseños y buena funcionalidad? Estaré feliz de ayudarte a conseguir lo que estás buscando!
                        </p>    
                        <a href="mailto:dbarrera.ap@gmail.com" className="btn btn-outline-light text-uppercase d-block d-md-inline  fs-6 mt-4">Contáctame</a> 
                    </div> 
                </div>
            </div>
        </div>
      </div>

      <section className="bg py-5 my-5" id="portafolio">
        <div className="container-xl my-2">
          <PortfolioGrid proyectos={proyectos} home={true} />
        </div>
      </section>

      <section className="container-xl my-5 py-5" id="tecnologias">
        <h2 className="fw-bold"><i className="fas fa-code"></i> Tecnologías que Utilizo   </h2>
        <div className="row justify-content-md-center mt-5">
            <div className="col-md-10 align-self-center mt-3 pt-4">  
                <ul className="nav justify-content-between">
                    <li className="text-center nav-item">
                        <i className="fab fa-html5 fa-4x" style={{color: '#e34c26'}}></i>
                        <p className="fw-bold">HTML5</p>
                    </li>
                    <li className="text-center nav-item">
                        <i className="fab fa-css3-alt fa-4x" style={{color: '#2965f1'}}></i>
                        <p className="fw-bold">CSS3</p>
                    </li>
                    <li className="nav-item text-center">
                        <i className="fab fa-js-square fa-4x" style={{color: '#f0db4f'}}></i>
                        <p className="fw-bold">JavaScript</p>
                    </li>
                    <li className="nav-item text-center">
                        <i className="fab fa-bootstrap fa-4x" style={{color: '#563d7c'}}></i>
                        <p className="fw-bold">Boostrap</p>
                    </li>
                    <li className="nav-item text-center">
                        <i className="fab fa-react fa-4x" style={{color: 'rgb(0, 216, 255)'}}></i>
                        <p className="fw-bold">React</p>
                    </li>
                </ul>
            </div>   
            <div className="col-md-10 align-self-center mb-5 pt-5">
                <ul className="nav justify-content-between">
                    <li className="nav-item text-center">
                        <i className="fab fa-node fa-4x" style={{color: '#3c873a'}}></i>
                        <p className="fw-bold">Node.js</p>
                    </li>
                    <li className="nav-item text-center">
                        <i className="fab fa-gulp fa-4x" style={{color: '#db4446'}}></i>
                        <p className="fw-bold">Gulp</p>
                    </li>
                    <li className="nav-item text-center">
                        <i className="fab fa-sass fa-4x" style={{color: '#cd6799'}}></i>
                        <p className="fw-bold">SASS</p>
                    </li>
                    <li className="nav-item text-center">
                        <i className="fab fa-php fa-4x" style={{color: '#787cb5'}}></i>
                        <p className="fw-bold">PHP</p>
                    </li>
                    <li className="nav-item text-center">
                        <i className="fas fa-database fa-4x" style={{color: '#f29111'}}></i>
                        <p className="fw-bold">MySQL</p>
                    </li>
                </ul> 
                        </div>                                      
                </div>      
            </section>
    </>
  )
}

export async function getStaticProps(){
  const proyectos = (datos && datos.portafolio) || []
  return { props: { proyectos } }
}
